const { withAndroidManifest, withDangerousMod, withMainActivity, withMainApplication, withAppBuildGradle } = require("expo/config-plugins");
const fs = require("node:fs/promises");
const path = require("node:path");

// Generated by prebuild; do not hand-edit android/. Debug exceptions only allow local testing.
const productionNetwork = `<?xml version="1.0" encoding="utf-8"?>
<network-security-config><base-config cleartextTrafficPermitted="false"><trust-anchors><certificates src="system" /></trust-anchors></base-config></network-security-config>`;
const debugNetwork = productionNetwork.replace("</network-security-config>", `<domain-config cleartextTrafficPermitted="true"><domain>localhost</domain><domain>127.0.0.1</domain><domain>10.0.2.2</domain></domain-config></network-security-config>`);
const exclude = ["root", "file", "database", "sharedpref", "external", "device_root", "device_file", "device_database", "device_sharedpref"].map(domain => `<exclude domain="${domain}" path="." />`).join("");
const releaseGuard = `
// BEGIN BOKJI RELEASE SECURITY
// Ninja on Windows cannot stat generated codegen object paths beyond MAX_PATH.
// Keep the staging directory short and let CMake hash long source paths.
if (System.getProperty('os.name').toLowerCase().contains('windows')) {
    android {
        externalNativeBuild {
            cmake { buildStagingDirectory file('../../../../tmp/cxx') }
        }
        defaultConfig {
            externalNativeBuild {
                cmake { arguments '-DCMAKE_OBJECT_PATH_MAX=240' }
            }
        }
    }
}
dependencies {
    constraints {
        implementation('com.google.code.gson:gson:2.10.1') { because 'CVE-2022-25647: patched deserialization; retain newer transitive versions' }
        implementation('commons-io:commons-io:2.17.0') { because 'CVE-2021-29425 and CVE-2024-47554: patched path validation and bounded parsing' }
    }
}
tasks.configureEach { task ->
    if (task.name ==~ /(?i)(createBundle.*ReleaseJsAndAssets|package.*Release.*|bundle.*Release|assemble.*Release)/) {
        task.doFirst {
            def raw = System.getenv('EXPO_PUBLIC_API_BASE_URL') ?: ''
            def uri
            try { uri = new URI(raw) } catch (Exception ignored) { throw new GradleException('Set a real HTTPS EXPO_PUBLIC_API_BASE_URL for release.') }
            def host = uri.host ?: ''
            if (uri.scheme != 'https' || !host || uri.userInfo || uri.query || uri.fragment || host ==~ /(?i)(localhost|.*\\.(invalid|test|example)|127\\..*|10\\..*|192\\.168\\..*|172\\.(1[6-9]|2[0-9]|3[01])\\..*|.*:.*)/) {
                throw new GradleException('Release requires a public HTTPS API URL without credentials, query or fragment.')
            }
        }
    }
}
// END BOKJI RELEASE SECURITY
`;

module.exports = function withSecurity(config) {
  config = withAndroidManifest(config, mod => {
    const app = mod.modResults.manifest.application[0].$;
    app["android:allowBackup"] = "false";
    app["android:usesCleartextTraffic"] = "false";
    app["android:networkSecurityConfig"] = "@xml/bokji_network_security";
    app["android:fullBackupContent"] = "@xml/bokji_backup_rules";
    app["android:dataExtractionRules"] = "@xml/bokji_data_extraction_rules";
    return mod;
  });
  config = withDangerousMod(config, ["android", async mod => {
    const root = path.join(mod.modRequest.platformProjectRoot, "app/src");
    const files = {
      "main/res/xml/bokji_network_security.xml": productionNetwork,
      "debug/res/xml/bokji_network_security.xml": debugNetwork,
      "main/res/xml/bokji_backup_rules.xml": `<full-backup-content>${exclude}</full-backup-content>`,
      "main/res/xml/bokji_data_extraction_rules.xml": `<data-extraction-rules><cloud-backup>${exclude}</cloud-backup><device-transfer>${exclude}</device-transfer></data-extraction-rules>`,
    };
    for (const [relative, contents] of Object.entries(files)) {
      const destination = path.join(root, relative);
      await fs.mkdir(path.dirname(destination), { recursive: true });
      await fs.writeFile(destination, contents + "\n");
    }
    for (const variant of ["debug", "debugOptimized"]) {
      const manifest = path.join(root, variant, "AndroidManifest.xml");
      try {
        const source = await fs.readFile(manifest, "utf8");
        await fs.writeFile(manifest, source.replace(/<uses-permission android:name="android.permission.SYSTEM_ALERT_WINDOW"\s*\/>/g, "").replace('android:usesCleartextTraffic="true"', 'android:usesCleartextTraffic="false"'));
      } catch (error) { if (error.code !== "ENOENT") throw error; }
    }
    return mod;
  }]);
  config = withMainActivity(config, mod => {
    if (!mod.modResults.contents.includes("FLAG_SECURE")) {
      const anchor = "super.onCreate(null)";
      if (!mod.modResults.contents.includes(anchor)) throw new Error("Security plugin: MainActivity template changed; review capture protection.");
      mod.modResults.contents = mod.modResults.contents.replace(anchor, `${anchor}\n    window.setFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE, android.view.WindowManager.LayoutParams.FLAG_SECURE)`);
    }
    return mod;
  });
  config = withMainApplication(config, mod => {
    if (!mod.modResults.contents.includes("setOkHttpClientFactory")) {
      const anchor = "super.onCreate()";
      if (!mod.modResults.contents.includes(anchor)) throw new Error("Security plugin: MainApplication template changed; review redirect protection.");
      mod.modResults.contents = mod.modResults.contents.replace(anchor, `${anchor}
    com.facebook.react.modules.network.OkHttpClientProvider.setOkHttpClientFactory {
      com.facebook.react.modules.network.OkHttpClientProvider.createClientBuilder()
        .followRedirects(false).followSslRedirects(false).build()
    }`);
    }
    return mod;
  });
  return withAppBuildGradle(config, mod => {
    // Local releases are unsigned until a real signing config is supplied (EAS supplies its own).
    mod.modResults.contents = mod.modResults.contents.replace(/(release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/, "$1signingConfig null");
    // Refresh existing generated blocks so plugin updates apply without --clean.
    mod.modResults.contents = mod.modResults.contents.replace(/\r?\n\/\/ BEGIN BOKJI RELEASE SECURITY[\s\S]*?\/\/ END BOKJI RELEASE SECURITY\r?\n?/, "") + releaseGuard;
    return mod;
  });
};
